/* For [[Module:Formatting]] */
.custom-formatting-code {
	display: inline-block;
	line-height: 21px;
}
.custom-formatting-code.code-block-table {
	display: table;
}
span.variable {
	opacity: 0.65;
}
span.variable::after {
	opacity: 0.65;
	content: "&gt;";
}
span.variable::before {
	opacity: 0.65;
	content: "&lt;";
}
.custom-formatting-nested {
	display: none;
}
.custom-formatting-resulting {
	display: inline;
}
.custom-formatting-code .custom-formatting-nested {
	display: inline-block;
}
.custom-formatting-code .custom-formatting-resulting {
	display: none;
}
/* End for [[Module:Formatting]] */

/**
 * CSS for [[Module:Documentation]] and [[Template:Documentation]]
 */

/**
 * ======================
 * Template documentation
 * ======================
 */
.template-documentation {
	border: 1px solid #CCC;
	border-color: #4b4b58;
	margin: 1em 0;
	background-color: #313139;
}

.template-documentation .template-documentation-header {
	background-color: #EEE;
	background-color: #25252b;
	border-bottom: 1px solid #CCC;
	border-color: #4b4b58;
	padding: 1em;
}

.template-documentation .template-documentation-langs {
	background-color: #F6F6F6;
	background-color: #4b4b58;
	border-bottom: 1px solid #CCC;
	border-color: #4b4b58;
	display: flex;
	flex-wrap: wrap;
	list-style: none;
	margin: 0;
	padding: 0;
	padding-bottom: 0.5em
}

.template-documentation .template-documentation-langs li {
	margin: 0 0 0 1em;
	padding: 0.5em 0 0;
}

.template-documentation .template-documentation-langs li.selected {
	order: -1;
}

.template-documentation .template-documentation-langs li.selected a {
	color: black;
	font-weight: bold;
}

.template-documentation .template-documentation-content {
	overflow-y: auto;
	padding: 1em;
}

.template-documentation .template-documentation-footer {
	background-color: #EEE;
	background-color: #25252b;
	border-top: 1px solid #CCC;
	border-color: #4b4b58;
	font-size: 100%;
	padding: .5em 1em;
	text-align: right;
}

.doctable {
    border: #e2b892;
    background-color: #23232D;
}

.doctable th.doc-header {
    padding: 15px;
    background-color: #e2b892;
}

.doctable tr.links td {
    padding: 0;
}

.doctable tr.links td a, .doctable tr.links td .mw-selflink  {
    padding: 5px;
    display: block;
    /*font-family: 'BarlowBold', sans-serif;*/
    font-size: 16px;
    text-align: center;
    text-decoration: none;
    transition: 0.1s;
}

.doctable tr.links td a {
    background-color: #27517e;
    color: #fafaff;
    font-weight: 500;
}

.doctable tr.links td a:hover, .doctable tr.links td .mw-selflink {
    background-color: #337fd0;
    transition: 0.1s;
}

