.hatnote {
    border-left: 3px solid #008eff;
    padding: 3px 10px;
    border-radius: 3px;
    background: linear-gradient(145deg, rgba(0, 142, 255, 0.15) 0%, rgba(0, 142, 255, 0) 100%);
    margin: 5px 0;
}

.mbox.subjective-severity-2                                                   { --mbox-theme-color: rgba(255, 50, 50) }
.mbox.removed, .mbox.delete, .mbox.subjective-severity-4                                  { --mbox-theme-color: rgba(255, 50, 50) }
.mbox.community                                                                           { --mbox-theme-color: rgba(255, 214, 120) }
.mbox.stub																				  { --mbox-theme-color: rgba(255, 255, 119) }
.mbox.sandbox, .mbox.subjective-severity-0                                                { --mbox-theme-color: rgba(50, 225, 100) }
.mbox.cleanup, .mbox-underconstruction, .mbox.subjective-severity-3                       { --mbox-theme-color: rgba(255, 150, 50) }
.mbox.upcoming, .mbox.placeholderimage, .mbox.disambiguation, .mbox.subjective-severity-1 { --mbox-theme-color: rgba(50, 200, 255) }
.mbox.lua, .mbox.css                                                                      { --mbox-theme-color: rgba(40, 100, 200) }
.mbox.premium                                                                             { --mbox-theme-color: rgba(183, 162, 104) }

.mbox {
    display: flex;
    position: relative;
    border: 1px solid var(--mbox-theme-color);
/*     border-left-width: 8px; */
    border-left-color: var(--mbox-theme-color);
    border-radius: 3px;
    margin-bottom: 5px;
    min-height: 32px;
    border-width: 1px 1px 1px 3px;
	background-color: rgb(from var(--mbox-theme-color) r g b / 0.1);
}

.mbox.subjective {
    border-style: dashed;
    border-left-width: 1px;
    font-size: 14px;
}

body.mediawiki .mbox a:not(.new),
body.mediawiki .mbox a:not(.new):hover {
	color: var(--mbox-theme-color);
	background-image: none;
	padding-right: 0;
	font-weight: 600;
}

.mbox__content {
    display: table;
    box-sizing: border-box;
    width: 100%;
    padding: 8px 15px;
}

.mbox__content__wrapper {
    display: table-cell;
    vertical-align: middle;
}

.mbox__content__header {
    display: block;
    font-weight: bold;
}

.mbox__content__text {
    display: block;
	padding-right: 10px;
}

.mbox__close {
    position: absolute;
    right: 0;
    top: 0;
    padding: 2px 7px;
    font-weight: bold;
    font-size: 16px;
    color: #bbb;
    cursor: pointer;
    transition: all .15s ease-in;
}

.mbox__content__image {
    display: table-cell;
    width: 40px;
    height: 100%;
    text-align: center;
    vertical-align: middle;
    padding-right: 15px;
}

.mbox__content__text__comment {
    font-size: small;
}

