  animation: rarity-ethereal-text 2.5s linear infinite;
}

.rarity-rng-exotic {
  animation: rarity-exotic-text 2s linear infinite;
}

.rarity-rng-rgb {
  animation: rarity-rgb-text 1.5s linear infinite;
}

.rarity-rng-godlyplus {
  animation: rarity-godly-text 1.5s linear infinite;
}

@keyframes rarity-ethereal-text {
  0% { color: #555555; }
  25% { color: #aaaaaa; }
  50% { color: #ffffff; }
  75% { color: #808080; }
  100% { color: #555555; }
}

@keyframes rarity-exotic-text {
  0% { color: #80FFD9; }
  33% { color: #ffffff; }
  66% { color: #00ffaa; }
  100% { color: #80FFD9; }
}

@keyframes rarity-rgb-text {
  0% { color: #ff0000; }
  33% { color: #00ff00; }
  66% { color: #0000ff; }
  100% { color: #ff0000; }
}

@keyframes rarity-godly-text {
  0% { color: #ff1d1d; }
  16% { color: #ff9c23; }
  32% { color: #ffff00; }
  48% { color: #65ff6a; }
  64% { color: #80f2ff; }
  80% { color: #f238ff; }
  100% { color: #ff1d1d; }
}

.rarity-fish-common {
  animation: fish-common-color 2s ease-in-out infinite;
}

.rarity-fish-uncommon {
  animation: fish-uncommon-color 2s ease-in-out infinite;
}

.rarity-fish-rare {
  animation: fish-rare-color 2s ease-in-out infinite;
}

.rarity-fish-epic {
  animation: fish-epic-color 2s ease-in-out infinite;
}

.rarity-fish-legendary {
