  position: relative;
  overflow: hidden;

  flex: 1;
  min-height: 430px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  padding: 24px;
  box-sizing: border-box;
}

.entry-content-title {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  margin-bottom: 20px;
}

