  border: 3px solid #222831;
  border-radius: 999px;
  font-size: 22px;
  font-weight: bold;
  color: #4f8cff;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

