  font-size: 17px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  word-wrap: break-word;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
