.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;

  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;
