/* ===== Hidden page image ===== */

.hidden-pageimage {
  position: absolute;

  width: 0;
  height: 0;

  overflow: hidden;
}

.hidden-pageimage img {
  width: 0;
  height: 0;
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-choice-pill img {
  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  line-height: 1;

  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;

  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  gap: 18px;

  align-self: stretch;
}

.entry-side-pill {
  width: 170px;
  flex: 1;
  min-height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
}

.entry-side-pill img {
  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;

  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  gap: 12px;

  margin-bottom: 20px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Six fish subicons ===== */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  min-width: 0;
  height: 155px;

  padding: 8px 10px 4px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.fish-area-icon img {
  display: block;

  max-width: 95px;
  max-height: 95px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  width: 100%;

