}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* ===== Square fish subicon pillboxes ===== */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(3, 180px);
  justify-content: center;
  gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

