}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  gap: 8px;
  margin-bottom: 8px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
