/* ===== Hidden page image ===== */

.hidden-pageimage {
  position: absolute;

  width: 0;
  height: 0;

  overflow: hidden;
}

.hidden-pageimage img {
  width: 0;
  height: 0;
}
/* Remove MediaWiki-generated blank paragraphs */
.entry-subcontent-fish &gt; p {
  display: none;
  margin: 0;
  padding: 0;
}

/* Reduce the intended subtab gap */
.entry-subtabs {
  margin-bottom: 8px;
}

/* Ensure the compact rules override tablet/mobile heights */
.entry-library-items.entry-fish-menu-open {
  min-height: 0 ;
  align-items: flex-start;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0 ;
  height: auto;
  align-self: flex-start;
  padding-bottom: 12px;
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-choice-pill img {
  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  gap: 18px;

  align-self: stretch;
}

.entry-side-pill {
  width: 170px;
  flex: 1;
  min-height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
}

.entry-side-pill img {
  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;
  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  gap: 12px;
  margin-bottom: 8px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

.entry-subcontent-fish &gt; p {
  display: none;
  margin: 0;
  padding: 0;
}

/* ===== Five square fish subicons ===== */

.fish-area-menu {
  display: none;

  width: 100%;

  grid-template-columns: repeat(3, 180px);
  justify-content: center;
  gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  position: relative;
  top: -12px;

  width: 100%;
  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  word-wrap: break-word;
}

/*
 * Desktop second row:
 * shift icons 4 and 5 so the two boxes are centred.
 */

.fish-area-icon:nth-child(4),
.fish-area-icon:nth-child(5) {
  transform: translateX(97px);
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  cursor: pointer;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;
}

.entry-card:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-card img {
  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  inset: 0;
  z-index: 50;

  padding: 24px;

  background: #0b0f17;
  border-radius: 20px;
  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px 1fr 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  text-align: center;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-block;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  font-weight: bold;
  line-height: 1;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  cursor: pointer;
}

.entry-detail-back:hover {
