  height: auto;

  align-self: flex-start;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-side {
  align-self: flex-start;
}

.entry-library-items.entry-fish-menu-open .entry-side-pill {
  flex: 0 0 135px;
  min-height: 135px;
}

@media screen and (max-width: 900px) {
