    flex-wrap: wrap;
    margin-bottom: 8px;
  }

  .entry-subtab {
    padding: 7px 14px;
    font-size: 18px;
  }

  /* 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, 135px);
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;

    margin: 0;
    padding: 0;
  }

  .fish-area-icon {
    width: 135px;
    height: 135px;

    grid-column: auto;
    justify-self: center;

    padding: 6px;
    border-radius: 18px;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    top: -8px;
    margin-top: -5px;
    font-size: 14px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-heading {
    gap: 10px;
  }

  .fish-group-title {
    font-size: 22px;
  }

  .fish-group-back {
    padding: 7px 12px;
    font-size: 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;
    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;
    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    justify-self: center;
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
