/* ===== Very small phones ===== */

@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex: 0 0 100%;

    flex-direction: row;
    font-size: 16px;
  }

  .entry-side-pill img {
    max-width: 42px;
    max-height: 42px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(2, 120px);
    justify-content: center;
    column-gap: 8px;
    row-gap: 8px;
  }

  .fish-area-icon {
    width: 120px;
    height: 120px;

    grid-column: auto;
    justify-self: center;

    padding: 5px;
    border-radius: 16px;
  }

  .fish-area-icon img {
    max-width: 70px;
    max-height: 70px;
  }

  .fish-area-name {
    top: -6px;
    margin-top: -4px;
    font-size: 12px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-title {
    font-size: 19px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}

