  .entry-side-pill {
    width: auto;
    min-width: 0;
    min-height: 92px;
    flex: 1;

    padding: 8px 4px;

    border-width: 3px;
    border-radius: 16px;

    font-size: 14px;
  }

  .entry-side-pill img {
    max-width: 48px;
    max-height: 48px;
  }

  .entry-content {
    min-height: 500px;
    padding: 14px;

