  }

  .entry-content-title {
    margin-bottom: 14px;

    font-size: 30px;
  }

  .entry-subtabs {
    gap: 8px;
    margin-bottom: 14px;
  }

  .entry-subtab {
    padding: 7px 13px;

    border-width: 2px;
    font-size: 18px;
  }

  /* Mobile: 2 + 2 + 1 centred */

  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 135px));
    justify-content: center;
    column-gap: 10px;
    row-gap: 10px;
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 135px;
    height: 135px;
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-area-icon img {
    max-width: 82px;
    max-height: 82px;
  }

  .fish-area-name {
    margin-top: -2px;

    font-size: 15px;
  }

  .entries-grid {
    gap: 9px;
  }

  .entry-card {
    width: 112px;
    height: 134px;
    padding: 8px;

    border-radius: 15px;
  }

  .entry-card img {
    max-width: 86px;
    max-height: 86px;
  }

  .entry-card-name {
    margin-top: -24px;

    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 16px;

    border-radius: 14px;
  }

  .entry-detail-top {
    grid-template-columns: 84px minmax(0, 1fr);
    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

