    padding-bottom: 10px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side-pill {
    flex: 0 0 120px !important;

    height: 120px !important;
    min-height: 120px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0 !important;
    padding-bottom: 10px !important;
  }
}

/* ===== Mobile ===== */

@media (max-width: 650px) {
  .entry-library-items.entry-fish-menu-open {
    align-items: stretch !important;

    padding-bottom: 8px !important;
  }

  .entry-library-items.entry-fish-menu-open .entry-side {
    align-self: auto !important;
