  }

  .fish-area-icon {
    width: 160px;
    height: 160px;
  }

  .fish-area-icon img {
    max-width: 100px;
    max-height: 100px;
  }

  .entry-detail-top {
    grid-template-columns: 130px minmax(0, 1fr) 90px;
    gap: 14px;
  }

  .entry-detail-image img {
    max-width: 115px;
    max-height: 115px;
  }

  .entry-detail-name {
    font-size: 34px;
  }
}

