    gap: 12px;
  }

  .entry-detail-image img {
    max-width: 78px;
    max-height: 78px;
  }

  .entry-detail-header {
    align-items: flex-start;
  }

  .entry-detail-name {
    font-size: 27px;
    text-align: left;
  }

  .entry-detail-rarity {
    text-align: left;
  }

  .entry-rarity-pill {
    padding: 6px 10px;

    font-size: 13px;
  }

  .entry-detail-back {
    grid-column: 1 / -1;
    justify-self: stretch;

    text-align: center;
  }

  .entry-detail-stats {
    grid-template-columns: 1fr;
    gap: 9px;

    margin-top: 18px;
  }

  .entry-detail-stat {
    padding: 12px;
  }

  .entry-detail-stat-value {
    font-size: 17px;
  }

  .entry-detail-body {
    padding: 13px;

    font-size: 16px;
  }
}

/* ===== Very small screens ===== */

@media (max-width: 360px) {
  .fish-area-menu {
    grid-template-columns: repeat(2, minmax(0, 118px));
  }

  .fish-area-icon,
  .fish-area-icon:nth-child(4),
  .fish-area-icon:nth-child(5) {
    width: 118px;
    height: 125px;
  }

  .fish-area-icon img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card {
    width: 104px;
