  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    justify-self: center;
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* ===== Very small phones ===== */

@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex: 0 0 100%;

    flex-direction: row;
    font-size: 16px;
  }

  .entry-side-pill img {
    max-width: 42px;
    max-height: 42px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(2, 120px);
    justify-content: center;
    column-gap: 8px;
    row-gap: 8px;
  }

  .fish-area-icon {
    width: 120px;
    height: 120px;

    grid-column: auto;
    justify-self: center;

    padding: 5px;
    border-radius: 16px;
  }

  .fish-area-icon img {
    max-width: 70px;
    max-height: 70px;
  }

  .fish-area-name {
    top: -6px;
    margin-top: -4px;
    font-size: 12px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-title {
    font-size: 19px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}

/* ===== Compact fish-menu screen ===== */

/*
 * The fish content panel becomes shorter.
 * Items, Tools and Enchants keep their original
 * equal sidebar spacing.
 */

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0;
  height: auto;

  align-self: flex-start;
  padding-bottom: 12px;
}

@media screen and (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
  }
}

@media screen and (max-width: 600px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
    padding-bottom: 8px;
  }
}

/* ===== Hidden page image ===== */

.hidden-pageimage {
  position: absolute;

  width: 0;
  height: 0;

  overflow: hidden;
}

.hidden-pageimage img {
  width: 0;
  height: 0;
}

.entry-ui {
  width: 100%;
  max-width: 1075px;
  box-sizing: border-box;
}

/* ===== Main category selection ===== */

.entry-choice-box {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 28px;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;
  padding: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;
  box-sizing: border-box;
}

.entry-choice-pill {
  width: 320px;
  height: 300px;
  flex: 0 0 320px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 26px;

  text-align: center;
  box-sizing: border-box;
  cursor: pointer;
}

.entry-choice-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-choice-pill img {
  max-width: 220px;
  max-height: 220px;
  width: auto;
  height: auto;
}

.entry-choice-text {
  display: block;

  color: #4f8cff;
  font-size: 50px;
  line-height: 1;
  white-space: nowrap;
}

/* ===== Entry library ===== */

.entry-library {
  display: none;

  width: 100%;
  max-width: 1075px;
  min-height: 500px;

  padding: 24px;
  gap: 24px;

  background: #07122b;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

/* ===== Left navigation ===== */

.entry-side {
  width: 190px;
  flex: 0 0 190px;

  display: flex;
  flex-direction: column;
  gap: 18px;

  align-self: stretch;
}

.entry-side-pill {
  width: 170px;
  flex: 1;
  min-height: 135px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  color: #4f8cff;
  font-size: 24px;
  font-weight: bold;
  line-height: 1;
  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
}

.entry-side-pill img {
  max-width: 80px;
  max-height: 80px;
  width: auto;
  height: auto;
}

.entry-side-pill div {
  margin-top: 0;
}

.entry-side-pill:hover {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Main content ===== */

.entry-content {
  position: relative;
  overflow: hidden;

  flex: 1;
  min-width: 0;
  min-height: 430px;

  padding: 24px;

  background: #0b0f17;
  border: 4px solid #222831;
  border-radius: 24px;

  box-sizing: border-box;
}

.entry-content-title {
  margin-bottom: 20px;

  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
}

/* ===== Item subtabs ===== */

.entry-subtabs {
  display: flex;
  gap: 12px;
  margin-bottom: 8px;
}

.entry-subtab {
  padding: 8px 18px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 999px;

  color: #4f8cff;
  font-size: 22px;
  font-weight: bold;

  cursor: pointer;
}

.entry-subtab:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.entry-subcontent {
  display: none;
}

/* Remove empty MediaWiki paragraphs */

.entry-subcontent-fish &gt; p {
  display: none;
  margin: 0;
  padding: 0;
}

/* ===== Fish subicon menu ===== */

.fish-area-menu {
  display: none;

  width: 100%;

  /*
   * Each icon spans two 83px columns:
   * 83px + 14px gap + 83px = 180px.
   */
  grid-template-columns: repeat(6, 83px);
  justify-content: center;
  column-gap: 14px;
  row-gap: 14px;

  margin: 0;
  padding: 0;

  box-sizing: border-box;
}

.fish-area-icon {
  width: 180px;
  height: 180px;
  min-width: 0;

  grid-column: span 2;
  justify-self: center;

  padding: 10px 8px 6px;

  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 22px;

  text-align: center;

  box-sizing: border-box;
  cursor: pointer;
  overflow: hidden;
}

.fish-area-icon:hover {
  background: #10275a;
  border-color: #5aaeff;
}

.fish-area-icon img {
  display: block;

  max-width: 115px;
  max-height: 115px;
  width: auto;
  height: auto;

  margin: 0 auto;
}

.fish-area-name {
  position: relative;
  top: -12px;

  width: 100%;
  margin-top: -5px;
  padding: 0;

  color: #4f8cff;
  font-size: 18px;
  font-weight: bold;
  line-height: 1;

  text-align: center;
  white-space: normal;
  word-wrap: break-word;
}

/* Centre subicons 4 and 5 on the second row */

.fish-area-icon:nth-child(4) {
  grid-column: 2 / span 2;
}

.fish-area-icon:nth-child(5) {
  grid-column: 4 / span 2;
}

.fish-area-icon.entry-active {
  background: #17346b;
  border-color: #5aaeff;
}

/* ===== Selected fish group ===== */

.fish-group {
  display: none;
}

.fish-group-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;

  margin-bottom: 18px;
}

.fish-group-title {
  color: #4f8cff;
  font-size: 28px;
  font-weight: bold;
}

.fish-group-back {
  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;

  cursor: pointer;
}

.fish-group-back:hover {
  background: #1f4388;
}

/* ===== Entry cards ===== */

.entries-grid {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: 12px;
}

.entry-card {
  position: relative;

  width: 130px;
  height: 150px;
  padding: 10px;

  background: #0b0f17;
  border: 3px solid #222831;
  border-radius: 18px;

  text-align: center;

  box-sizing: border-box;
  overflow: visible;
  cursor: pointer;
}

.entry-card:hover {
  background: #10275a;
}

.entry-card img {
  max-width: 100px;
  max-height: 100px;
  width: auto;
  height: auto;
}

.entry-card-name {
  margin-top: -30px;

  font-size: 16px;
  font-weight: bold;
  line-height: 1;
}

.entry-card-items {
  border-color: #5aaeff;
}

.entry-card-tools {
  border-color: #69e8f4;
}

.entry-card-enchants {
  border-color: #9666ff;
}

/* ===== Entry detail page ===== */

.entry-detail-panel {
  display: none;

  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;

  z-index: 50;

  padding: 24px;

  background: #0b0f17;
  border-radius: 20px;

  box-sizing: border-box;
}

.entry-detail-top {
  display: grid;
  grid-template-columns: 160px 1fr 120px;
  align-items: center;
  gap: 20px;
}

.entry-detail-image {
  text-align: left;
}

.entry-detail-image img {
  max-width: 140px;
  max-height: 140px;
  width: auto;
  height: auto;
}

.entry-detail-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
}

.entry-detail-name {
  color: #4f8cff;
  font-size: 42px;
  font-weight: bold;
  text-align: center;
}

.entry-detail-rarity {
  text-align: center;
}

.entry-rarity-pill {
  display: inline-block;

  padding: 8px 16px;

  background: #0b0f17;
  border: 2px solid #222831;
  border-radius: 999px;

  font-weight: bold;
  line-height: 1;
}

.entry-detail-back {
  justify-self: end;
  display: inline-block;

  padding: 8px 14px;

  background: #10275a;
  border: 2px solid #5aaeff;
  border-radius: 12px;

  color: #ffffff;
  font-weight: bold;
  text-decoration: none;

  cursor: pointer;
}

.entry-detail-back:hover {
  background: #1f4388;
}

.entry-detail-body {
  margin-top: 28px;

  color: #ffffff;
  font-size: 18px;
  line-height: 1.4;
}

/* ===== Active states ===== */

.js-entry-open {
  cursor: pointer;
}

.entry-side-pill.entry-active,
.entry-subtab.entry-active {
  background: #10275a;
  border-color: #5aaeff;
}

/* ===== Rarity name animations ===== */

.entry-name-rarity-common {
  animation: fish-common-name 2s ease-in-out infinite;
}

.entry-name-rarity-uncommon {
  animation: fish-uncommon-name 2s ease-in-out infinite;
}

.entry-name-rarity-rare {
  animation: fish-rare-name 2s ease-in-out infinite;
}

.entry-name-rarity-epic {
  animation: fish-epic-name 2s ease-in-out infinite;
}

.entry-name-rarity-legendary {
  animation: fish-legendary-name 2s ease-in-out infinite;
}

.entry-name-rarity-mythic {
  animation: fish-mythic-name 2s ease-in-out infinite;
}
.entry-name-rarity-secret {
  animation: fish-secret-name 2s ease-in-out infinite;
}
@keyframes fish-common-name {
  0% {
    color: #a8b1b6;
  }

  50% {
    color: #7f8c99;
  }

  100% {
    color: #a8b1b6;
  }
}

@keyframes fish-uncommon-name {
  0% {
    color: #67ec88;
  }

  50% {
    color: #63c138;
  }

  100% {
    color: #67ec88;
  }
}

@keyframes fish-rare-name {
  0% {
    color: #4ad8ff;
  }

  50% {
    color: #3d93fc;
  }

  100% {
    color: #4ad8ff;
  }
}

@keyframes fish-epic-name {
  0% {
    color: #7843ff;
  }

  50% {
    color: #7246a7;
  }

  100% {
    color: #7843ff;
  }
}

@keyframes fish-legendary-name {
  0% {
    color: #ffe669;
  }

  50% {
    color: #fc932a;
  }

  100% {
    color: #ffe669;
  }
}

@keyframes fish-mythic-name {
  0% {
    color: #ff3045;
  }

  50% {
    color: #b11156;
  }

  100% {
    color: #ff3045;
  }
}

@keyframes fish-secret-color {
  0% {
    color: #a617ff;
  }

  50% {
    color: #ff26fb;
  }

  100% {
    color: #a617ff;
  }
}
/* ===== Rarity border animations ===== */

.entry-card-rarity-none {
  border-color: #222831;
  box-shadow: none;
}

.entry-card-rarity-common {
  animation: fish-common-border 2s ease-in-out infinite;
}

.entry-card-rarity-uncommon {
  animation: fish-uncommon-border 2s ease-in-out infinite;
}

.entry-card-rarity-rare {
  animation: fish-rare-border 2s ease-in-out infinite;
}

.entry-card-rarity-epic {
  animation: fish-epic-border 2s ease-in-out infinite;
}

.entry-card-rarity-legendary {
  animation: fish-legendary-border 2s ease-in-out infinite;
}

.entry-card-rarity-mythic {
  animation: fish-mythic-border 2s ease-in-out infinite;
}

@keyframes fish-common-border {
  0% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }

  50% {
    border-color: #7f8c99;
    box-shadow: 0 0 10px #7f8c99;
  }

  100% {
    border-color: #a8b1b6;
    box-shadow: 0 0 5px #a8b1b6;
  }
}

@keyframes fish-uncommon-border {
  0% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }

  50% {
    border-color: #63c138;
    box-shadow: 0 0 10px #63c138;
  }

  100% {
    border-color: #67ec88;
    box-shadow: 0 0 5px #67ec88;
  }
}

@keyframes fish-rare-border {
  0% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }

  50% {
    border-color: #3d93fc;
    box-shadow: 0 0 10px #3d93fc;
  }

  100% {
    border-color: #4ad8ff;
    box-shadow: 0 0 5px #4ad8ff;
  }
}

@keyframes fish-epic-border {
  0% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }

  50% {
    border-color: #7246a7;
    box-shadow: 0 0 10px #7246a7;
  }

  100% {
    border-color: #7843ff;
    box-shadow: 0 0 5px #7843ff;
  }
}

@keyframes fish-legendary-border {
  0% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }

  50% {
    border-color: #fc932a;
    box-shadow: 0 0 10px #fc932a;
  }

  100% {
    border-color: #ffe669;
    box-shadow: 0 0 5px #ffe669;
  }
}

@keyframes fish-mythic-border {
  0% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }

  50% {
    border-color: #b11156;
    box-shadow: 0 0 12px #b11156;
  }

  100% {
    border-color: #ff3045;
    box-shadow: 0 0 6px #ff3045;
  }
}

