    max-height: 82px;
  }

  .fish-area-name {
    top: -8px;
    margin-top: -5px;
    font-size: 14px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-heading {
    gap: 10px;
  }

  .fish-group-title {
    font-size: 22px;
  }

  .fish-group-back {
    padding: 7px 12px;
    font-size: 14px;
  }

  .entry-card {
    width: 110px;
    height: 135px;
    padding: 8px;
  }

  .entry-card img {
    max-width: 82px;
    max-height: 82px;
  }

  .entry-card-name {
    margin-top: -15px;
    font-size: 14px;
  }

  .entry-detail-panel {
    padding: 14px;
    overflow: auto;
  }

  .entry-detail-top {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  .entry-detail-image {
    text-align: center;
  }

  .entry-detail-image img {
    max-width: 110px;
    max-height: 110px;
  }

  .entry-detail-name {
    font-size: 30px;
  }

  .entry-detail-back {
    justify-self: center;
    text-align: center;
  }

  .entry-detail-body {
    font-size: 16px;
    text-align: center;
  }
}

/* ===== Very small phones ===== */

@media screen and (max-width: 380px) {
  .entry-choice-pill {
    height: 165px;
  }

  .entry-choice-pill img {
    max-width: 95px;
    max-height: 95px;
  }

  .entry-choice-text {
    font-size: 26px;
  }

  .entry-side-pill {
    width: 100%;
    height: 75px;
    flex: 0 0 100%;

    flex-direction: row;
    font-size: 16px;
  }

  .entry-side-pill img {
    max-width: 42px;
    max-height: 42px;
  }

  .fish-area-menu {
    grid-template-columns: repeat(2, 120px);
    justify-content: center;
    column-gap: 8px;
    row-gap: 8px;
  }

  .fish-area-icon {
    width: 120px;
    height: 120px;

    grid-column: auto;
    justify-self: center;

    padding: 5px;
    border-radius: 16px;
  }

  .fish-area-icon img {
    max-width: 70px;
    max-height: 70px;
  }

  .fish-area-name {
    top: -6px;
    margin-top: -4px;
    font-size: 12px;
  }

  .fish-area-icon:nth-child(4) {
    grid-column: auto;
  }

  .fish-area-icon:nth-child(5) {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .fish-group-title {
    font-size: 19px;
  }

  .entry-card {
    width: 95px;
    height: 125px;
  }

  .entry-card img {
    max-width: 72px;
    max-height: 72px;
  }

  .entry-card-name {
    font-size: 12px;
  }

  .entry-detail-name {
    font-size: 24px;
  }

  .entry-detail-body {
    font-size: 14px;
  }
}

/* ===== Compact fish-menu screen ===== */

/*
 * The fish content panel becomes shorter.
 * Items, Tools and Enchants keep their original
 * equal sidebar spacing.
 */

.entry-library-items.entry-fish-menu-open {
  min-height: 0;
  padding-bottom: 12px;
}

.entry-library-items.entry-fish-menu-open .entry-content {
  min-height: 0;
  height: auto;

  align-self: flex-start;
  padding-bottom: 12px;
}

@media screen and (max-width: 900px) {
  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
  }
}

@media screen and (max-width: 600px) {
  .entry-library-items.entry-fish-menu-open {
    min-height: 0;
    padding-bottom: 8px;
  }

  .entry-library-items.entry-fish-menu-open .entry-content {
    min-height: 0;
    padding-bottom: 8px;
  }
}

